    if (email === '') {
      res.status(400).send(page('Sign up', '<p>An email address is required.</p><p><a href="/signup">Back</a></p>'))
      return
    }
    try {
      await issueCode(email)
    } catch (error) {
      next(error)
      return
    }
    res.redirect(303, `/verify?email=${encodeURIComponent(email)}`)
